async function loadDashboardSlow(id) {
  const user = await getUser(id)
  const orders = await getOrders(id)
  const notes = await getNotifications(id)
  return { user, orders, notes }
}

// Concurrent: about 300 ms, all three requests are in flight together
async function loadDashboard(id) {
  const [user, orders, notes] = await Promise.all([
    getUser(id),
    getOrders(id),
    getNotifications(id)
  ])
  return { user, orders, notes }
}

// Ordering inside an async function
async function f() {
  console.log('B')     // runs synchronously, as part of the call
  await null
  console.log('D')     // resumes later, as a microtask
}
console.log('A')
f()
console.log('C')
// Output: A B C D

