const delay = (ms, value) => new Promise((resolve) => setTimeout(() => resolve(value), ms))
const elapsed = (start) => Math.round((Date.now() - start) / 100) * 100

async function sequential() {
  const start = Date.now()
  const a = await delay(300, 'user')
  const b = await delay(300, 'orders')
  const c = await delay(300, 'notes')
  console.log('sequential:', [a, b, c].join(', '), 'in about', elapsed(start), 'ms')
}

async function concurrent() {
  const start = Date.now()
  const [a, b, c] = await Promise.all([
    delay(300, 'user'),
    delay(300, 'orders'),
    delay(300, 'notes')
  ])
  console.log('concurrent:', [a, b, c].join(', '), 'in about', elapsed(start), 'ms')
}

sequential().then(concurrent)

