from concurrent.futures import ThreadPoolExecutor, ProcessPoolExecutor, as_completed
import requests

def download(url):
    r = requests.get(url, timeout=10)     # waiting on the network releases the GIL
    r.raise_for_status()
    return url, len(r.content)

def make_thumbnail(path):
    ...                                   # pure-Python pixel work: CPU-bound

def main():
    urls = [f"https://example.com/files/{i}.csv" for i in range(200)]

    # I/O-bound: threads. map yields results in input order.
    with ThreadPoolExecutor(max_workers=16) as pool:
        for url, size in pool.map(download, urls):
            print(url, size)

    # Per-task error handling with submit and as_completed
    with ThreadPoolExecutor(max_workers=16) as pool:
        futures = {pool.submit(download, u): u for u in urls}
        for fut in as_completed(futures):
            try:
                print(fut.result())
            except requests.RequestException as err:
                print("failed:", futures[fut], err)

    # CPU-bound: processes, one worker per core by default
    with ProcessPoolExecutor() as pool:
        list(pool.map(make_thumbnail, ["a.jpg", "b.jpg", "c.jpg"]))

if __name__ == "__main__":    # required for process pools on Windows and macOS
    main()

